+            databaseTmpGzFile = Files.createFile(geoipTmpDirectory.resolve(databaseName + ".tmp.gz"));
+        } catch (FileAlreadyExistsException e) {
+            LOGGER.debug("database update [{}] already in progress, skipping...", databaseName);
+            return;
+        }
